  `assign_date` date DEFAULT NULL,
  `assignment_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT 'assigned',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_asset_code` (`asset_code`),
  KEY `employee_code` (`employee_code`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `assets_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`product_id`) ON UPDATE CASCADE
