--
-- Table structure for table `item_fixed_asset_codes`
--

DROP TABLE IF EXISTS `item_fixed_asset_codes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `item_fixed_asset_codes` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `item_master_id` bigint unsigned NOT NULL,
  `grn_id` bigint unsigned DEFAULT NULL,
  `code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `a_code` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_assigned` tinyint(1) NOT NULL DEFAULT '0',
  `assigned_to` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_by` int DEFAULT NULL,
  `updated_by` int DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `item_fixed_asset_codes_code_unique` (`code`),
  KEY `item_fixed_asset_codes_item_master_id_foreign` (`item_master_id`),
  KEY `item_fixed_asset_codes_grn_id_foreign` (`grn_id`),
  CONSTRAINT `item_fixed_asset_codes_grn_id_foreign` FOREIGN KEY (`grn_id`) REFERENCES `grns` (`id`) ON DELETE SET NULL,
  CONSTRAINT `item_fixed_asset_codes_item_master_id_foreign` FOREIGN KEY (`item_master_id`) REFERENCES `item_masters` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9273 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

